// Checks the shared secret, reads the Vapi tool call and decides the route.
// Helper functions first (shared by the Code nodes of this template); the node logic is at the end.

// Helpers shared by the Code nodes of this template.
//
// Each Code node carries its own copy of the helper functions it needs, so
// every node works on its own. `DateTime` is Luxon, which n8n provides in Code nodes.

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

// First non-empty value among `keys`, as a trimmed string ('' if none).
function pickString(source, keys) {
  if (!isObject(source)) return '';
  for (const key of keys) {
    const value = source[key];
    if (typeof value === 'string' && value.trim() !== '') return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
}

// True for empty values and for placeholders that were not replaced, such as "CHANGE_ME".
function isPlaceholder(value) {
  if (typeof value !== 'string') return true;
  const text = value.trim();
  return text === '' || text.includes('{{') || /^change[_ -]?me/i.test(text);
}

// Shared-secret check for the webhooks.

// Compares two strings in a time that depends only on their length.
function safeEqual(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  let diff = a.length ^ b.length;
  const length = Math.max(a.length, b.length);
  for (let i = 0; i < length; i += 1) {
    diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  }
  return diff === 0;
}

// Accepts the secret in `headerName` (default "x-vapi-secret") or as
// "Authorization: Bearer <secret>", the two ways Vapi can send it.
// Fails closed while the secret is still a placeholder, so a workflow that was
// imported but not configured rejects every request.
function isAuthorized(headers, expectedSecret, headerName) {
  if (isPlaceholder(expectedSecret)) return false;
  const secret = expectedSecret.trim();

  const received = {};
  if (isObject(headers)) {
    for (const [key, value] of Object.entries(headers)) {
      received[key.toLowerCase()] = Array.isArray(value) ? value[0] : value;
    }
  }

  const name = (typeof headerName === 'string' && headerName.trim() ? headerName : 'x-vapi-secret')
    .trim()
    .toLowerCase();
  const fromHeader = typeof received[name] === 'string' ? received[name].trim() : undefined;

  const authorization = typeof received.authorization === 'string' ? received.authorization.trim() : '';
  const fromBearer = /^bearer\s+/i.test(authorization) ? authorization.replace(/^bearer\s+/i, '') : undefined;

  return safeEqual(fromHeader, secret) || safeEqual(fromBearer, secret);
}

// Vapi tool-call parsing and tool-result format.
//
// Vapi posts {"message": {"type": "tool-calls", "toolCallList": [...], ...}}.
// Each call has an `id` and either `function: {name, arguments}` or, in some
// examples of the docs, `name` and `parameters`. `arguments` can arrive as an
// object or as a JSON string. `message.toolWithToolCallList[].toolCall` carries
// the same calls, and the OpenAI-style `message.toolCalls` is accepted too.

function parseArguments(raw) {
  if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      return isObject(parsed) ? parsed : {};
    } catch (error) {
      return {};
    }
  }
  return isObject(raw) ? raw : {};
}

function listToolCalls(message) {
  if (!isObject(message)) return [];
  if (Array.isArray(message.toolCallList) && message.toolCallList.length) return message.toolCallList;
  if (Array.isArray(message.toolCalls) && message.toolCalls.length) return message.toolCalls;
  if (Array.isArray(message.toolWithToolCallList)) {
    return message.toolWithToolCallList
      .filter((entry) => isObject(entry) && isObject(entry.toolCall))
      .map((entry) => ({
        ...entry.toolCall,
        name: entry.toolCall.name || entry.name || (isObject(entry.function) ? entry.function.name : undefined),
      }));
  }
  return [];
}

// Returns {source, toolCallId, name, args}. Picks the call named `expectedName`
// if there is one, otherwise the first call. Without a Vapi envelope it falls
// back to the plain body, e.g. {"date": "2026-10-14", "time": "10:00"}.
function parseToolCall(body, expectedName) {
  const calls = listToolCalls(isObject(body) ? body.message : undefined)
    .filter(isObject)
    .map((call) => {
      const fn = isObject(call.function) ? call.function : {};
      return {
        source: 'vapi',
        toolCallId: typeof call.id === 'string' ? call.id : null,
        name: fn.name || call.name || null,
        args: parseArguments(fn.arguments !== undefined ? fn.arguments : (call.parameters !== undefined ? call.parameters : call.arguments)),
      };
    });

  if (calls.length) {
    return calls.find((call) => expectedName && call.name === expectedName) || calls[0];
  }

  const plain = isObject(body) ? body : {};
  return {
    source: 'plain',
    toolCallId: typeof plain.toolCallId === 'string' ? plain.toolCallId : null,
    name: expectedName || null,
    args: plain,
  };
}

// Vapi expects HTTP 200 with one entry per tool call; `result` and `error` must be flat strings.
function toolResult(toolCallId, payload) {
  return { results: [{ toolCallId, result: JSON.stringify(payload) }] };
}

function toolError(toolCallId, code, message) {
  return { results: [{ toolCallId, error: JSON.stringify({ status: 'error', code, message }) }] };
}

// Settings for the calendar tools, read from the "Configure me" node.
// The timezone has no default here: it is defined once, in that node.

// "9:30", "09:30" or "09:30:00" -> {hour, minute}; "10" -> {hour: 10, minute: 0}.
function parseClock(text) {
  const match = /^(\d{1,2})(?::(\d{2}))?(?::\d{2})?$/.exec(String(text === undefined || text === null ? '' : text).trim());
  if (!match) return null;
  const hour = Number(match[1]);
  const minute = match[2] === undefined ? 0 : Number(match[2]);
  if (hour > 23 || minute > 59) return null;
  return { hour, minute };
}

function positiveInteger(value, fallback) {
  const number = Number(value);
  return Number.isInteger(number) && number > 0 ? number : fallback;
}

function nonNegativeInteger(value, fallback) {
  const number = Number(value);
  return Number.isInteger(number) && number >= 0 ? number : fallback;
}

// Language of the weekday names returned to the agent, e.g. "en", "es", "de".
function readLocale(value) {
  const locale = typeof value === 'string' && value.trim() ? value.trim() : 'en';
  try {
    if (Intl.DateTimeFormat.supportedLocalesOf([locale]).length) return locale;
  } catch (error) {
    // Malformed language tag: reported below.
  }
  throw new Error(`Settings: invalid locale "${value}"`);
}

// Throws if a required setting is missing or invalid.
function readSettings(raw) {
  const source = isObject(raw) ? raw : {};

  const timezone = typeof source.timezone === 'string' ? source.timezone.trim() : '';
  if (!timezone || !DateTime.now().setZone(timezone).isValid) {
    throw new Error(`Settings: missing or invalid timezone "${source.timezone}"`);
  }

  // "primary" is the main calendar of the connected Google account.
  const calendarId = source.calendarId === undefined ? 'primary' : String(source.calendarId).trim();
  if (isPlaceholder(calendarId)) throw new Error('Settings: set calendarId ("primary" or a calendar ID)');

  const openFrom = parseClock(source.openFrom === undefined ? '09:00' : source.openFrom);
  const openTo = parseClock(source.openTo === undefined ? '18:00' : source.openTo);
  if (!openFrom || !openTo || openTo.hour * 60 + openTo.minute <= openFrom.hour * 60 + openFrom.minute) {
    throw new Error('Settings: invalid opening hours');
  }

  // Luxon weekdays: 1 = Monday ... 7 = Sunday.
  const openDays = String(source.openDays === undefined ? '1,2,3,4,5' : source.openDays)
    .split(',')
    .map((day) => Number(day.trim()))
    .filter((day) => Number.isInteger(day) && day >= 1 && day <= 7);
  if (!openDays.length) throw new Error('Settings: no opening days');

  const eventTitle = typeof source.eventTitle === 'string' && source.eventTitle.trim() ? source.eventTitle.trim() : 'Appointment';

  return {
    timezone,
    calendarId,
    openDays,
    openFrom,
    openTo,
    slotMinutes: positiveInteger(source.slotMinutes, 30),
    stepMinutes: positiveInteger(source.stepMinutes, 30),
    alternatives: positiveInteger(source.alternatives, 3),
    searchDays: positiveInteger(source.searchDays, 7),
    minNoticeMinutes: nonNegativeInteger(source.minNoticeMinutes, 60),
    locale: readLocale(source.locale),
    eventTitle,
  };
}

// Slot rules: requested slot, opening hours, busy intervals and alternatives.
// Times are Luxon DateTimes in the configured timezone.

// Reads {date: "YYYY-MM-DD", time: "HH:mm"}. Also accepts one combined
// "YYYY-MM-DD HH:mm" (or ISO "YYYY-MM-DDTHH:mm") value in `datetime`.
function readSlotArgs(args) {
  let date = pickString(args, ['date']);
  let time = pickString(args, ['time']);
  const combined = pickString(args, ['datetime', 'dateTime', 'date_time']);
  if ((!date || !time) && combined) {
    const match = /^(\d{4}-\d{2}-\d{2})[ T](\d{1,2}:\d{2})/.exec(combined);
    if (match) {
      date = date || match[1];
      time = time || match[2];
    }
  }
  return { date, time };
}

// The requested start, in the configured timezone, and its end after the visit duration.
function toSlot(date, time, settings) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date || '')) {
    return { ok: false, code: 'invalid_date', message: 'date must be YYYY-MM-DD' };
  }
  const clock = parseClock(time);
  if (!clock) return { ok: false, code: 'invalid_time', message: 'time must be HH:mm' };
  const start = DateTime.fromISO(date, { zone: settings.timezone }).set({ hour: clock.hour, minute: clock.minute });
  if (!start.isValid) return { ok: false, code: 'invalid_date', message: 'date is not a valid date' };
  return { ok: true, start, end: start.plus({ minutes: settings.slotMinutes }) };
}

function isWithinOpeningHours(start, end, settings) {
  const local = start.setZone(settings.timezone);
  if (!settings.openDays.includes(local.weekday)) return false;
  const open = local.set({ hour: settings.openFrom.hour, minute: settings.openFrom.minute, second: 0, millisecond: 0 });
  const close = local.set({ hour: settings.openTo.hour, minute: settings.openTo.minute, second: 0, millisecond: 0 });
  return start >= open && end <= close;
}

// Why a slot cannot be offered regardless of the calendar, or null.
function slotProblem(start, end, settings, now) {
  if (start < now) return 'in_the_past';
  if (start < now.plus({ minutes: settings.minNoticeMinutes })) return 'too_soon';
  if (!isWithinOpeningHours(start, end, settings)) return 'outside_opening_hours';
  return null;
}

function toIntervals(busy) {
  return (Array.isArray(busy) ? busy : [])
    .filter(isObject)
    .map((entry) => ({ start: DateTime.fromISO(String(entry.start)), end: DateTime.fromISO(String(entry.end)) }))
    .filter((entry) => entry.start.isValid && entry.end.isValid && entry.end > entry.start);
}

function overlapsAny(start, end, intervals) {
  return intervals.some((interval) => start < interval.end && interval.start < end);
}

// A slot is free only if no busy interval overlaps any part of it.
function isSlotFree(start, end, busy) {
  return !overlapsAny(start, end, toIntervals(busy));
}

// Busy intervals from a Google Calendar freeBusy response (the n8n "Availability"
// operation with output format RAW). Returns null when the response cannot be
// read, so the caller never reports a slot as free without calendar data.
function busyFromFreeBusy(response) {
  if (!isObject(response) || !isObject(response.calendars)) return null;
  const calendars = Object.values(response.calendars).filter(isObject);
  if (!calendars.length) return null;
  if (calendars.some((calendar) => Array.isArray(calendar.errors) && calendar.errors.length)) return null;
  if (calendars.some((calendar) => !Array.isArray(calendar.busy))) return null;
  return calendars.reduce((all, calendar) => all.concat(calendar.busy), []);
}

// Days searched for alternatives: `searchDays` around the requested day, never before today.
// The freeBusy query covers the same range, so every alternative was checked against it.
function searchRange(requestedStart, settings, now) {
  const today = now.setZone(settings.timezone).startOf('day');
  const from = DateTime.max(requestedStart.minus({ days: settings.searchDays }).startOf('day'), today);
  const to = DateTime.max(requestedStart, now.setZone(settings.timezone)).plus({ days: settings.searchDays }).endOf('day');
  return { from, to };
}

// The `settings.alternatives` free slots closest in time to the requested one,
// inside opening hours and the notice period, returned in chronological order.
function findAlternatives(requestedStart, busy, settings, now) {
  const intervals = toIntervals(busy);
  const { from, to } = searchRange(requestedStart, settings, now);
  const earliest = now.plus({ minutes: settings.minNoticeMinutes });
  const candidates = [];

  for (let day = from.startOf('day'); day <= to; day = day.plus({ days: 1 })) {
    if (!settings.openDays.includes(day.weekday)) continue;
    const close = day.set({ hour: settings.openTo.hour, minute: settings.openTo.minute });
    let start = day.set({ hour: settings.openFrom.hour, minute: settings.openFrom.minute });
    while (start.plus({ minutes: settings.slotMinutes }) <= close) {
      const end = start.plus({ minutes: settings.slotMinutes });
      if (start >= earliest && start.toMillis() !== requestedStart.toMillis() && !overlapsAny(start, end, intervals)) {
        candidates.push(start);
      }
      start = start.plus({ minutes: settings.stepMinutes });
    }
  }

  const target = requestedStart.toMillis();
  candidates.sort((a, b) => Math.abs(a.toMillis() - target) - Math.abs(b.toMillis() - target) || a.toMillis() - b.toMillis());
  return candidates.slice(0, settings.alternatives).sort((a, b) => a.toMillis() - b.toMillis());
}

// Short description for the agent; `weekday` saves the model from computing it.
function describeSlot(start, settings) {
  const locale = isObject(settings) && settings.locale ? settings.locale : 'en';
  return { date: start.toFormat('yyyy-MM-dd'), time: start.toFormat('HH:mm'), weekday: start.setLocale(locale).toFormat('cccc') };
}

function checkAvailability(start, end, busy, settings, now) {
  const reason = slotProblem(start, end, settings, now) || (isSlotFree(start, end, busy) ? null : 'busy');
  if (!reason) return { available: true, ...describeSlot(start, settings) };
  return {
    available: false,
    reason,
    alternatives: findAlternatives(start, busy, settings, now).map((slot) => describeSlot(slot, settings)),
  };
}

// Steps of the workflow. Every step returns the JSON of the node's output
// item; `statusCode` and `response` are what "Respond to Vapi" sends back.

const CHECK_AVAILABILITY = 'check_availability';
const BOOK_APPOINTMENT = 'book_appointment';

function readBookingArgs(args) {
  const { date, time } = readSlotArgs(args);
  const booking = {
    name: pickString(args, ['name', 'fullName', 'full_name']),
    phone: pickString(args, ['phone', 'phoneNumber', 'phone_number']),
    email: pickString(args, ['email', 'emailAddress']),
    date,
    time,
  };
  booking.missing = ['name', 'phone', 'date', 'time'].filter((field) => !booking[field]);
  return booking;
}

// Title and description of the calendar event. The email is optional.
function eventFields(booking, settings) {
  const lines = [`Phone: ${booking.phone}`];
  if (booking.email) lines.push(`Email: ${booking.email}`);
  return {
    summary: `${settings.eventTitle} - ${booking.name}`,
    description: lines.join('\n'),
  };
}

// "Parse and validate tool call": checks the secret, reads the tool call and decides the route.
// `item` is the webhook item plus `endpointTool` and `settings` from the Set nodes.
function prepareToolRequest(item, now) {
  const input = isObject(item) ? item : {};
  const rawSettings = isObject(input.settings) ? input.settings : {};
  if (!isAuthorized(input.headers, rawSettings.webhookSecret, rawSettings.secretHeader)) {
    return { route: 'respond', statusCode: 401, response: { error: 'unauthorized' } };
  }

  const tool = input.endpointTool;
  const call = parseToolCall(input.body, tool);
  const fail = (code, message) => ({ route: 'respond', statusCode: 200, response: toolError(call.toolCallId, code, message) });

  let settings;
  try {
    settings = readSettings(rawSettings);
  } catch (error) {
    return fail('server_misconfigured', error.message);
  }

  if (tool === CHECK_AVAILABILITY) {
    const { date, time } = readSlotArgs(call.args);
    const slot = toSlot(date, time, settings);
    if (!slot.ok) return fail(slot.code, slot.message);
    const range = searchRange(slot.start, settings, now);
    return {
      route: 'availability',
      statusCode: 200,
      tool,
      toolCallId: call.toolCallId,
      settings,
      slot: { start: slot.start.toISO(), end: slot.end.toISO() },
      query: { timeMin: range.from.toISO(), timeMax: range.to.toISO() },
    };
  }

  if (tool === BOOK_APPOINTMENT) {
    const booking = readBookingArgs(call.args);
    if (booking.missing.length) return fail('missing_fields', `Missing: ${booking.missing.join(', ')}`);
    const slot = toSlot(booking.date, booking.time, settings);
    if (!slot.ok) return fail(slot.code, slot.message);
    const problem = slotProblem(slot.start, slot.end, settings, now);
    if (problem) return fail(problem, 'This slot cannot be booked. Check availability again.');
    return {
      route: 'booking',
      statusCode: 200,
      tool,
      toolCallId: call.toolCallId,
      settings,
      slot: { start: slot.start.toISO(), end: slot.end.toISO() },
      query: { timeMin: slot.start.toISO(), timeMax: slot.end.toISO() },
      event: { ...eventFields(booking, settings), start: slot.start.toISO(), end: slot.end.toISO() },
    };
  }

  return fail('unknown_tool', `This endpoint does not serve "${tool}"`);
}

function slotFromPrepared(prepared) {
  const zone = prepared.settings.timezone;
  return {
    start: DateTime.fromISO(prepared.slot.start, { zone }),
    end: DateTime.fromISO(prepared.slot.end, { zone }),
  };
}

// "Build availability result": the requested slot against the busy intervals of the search range.
function availabilityResponse(prepared, freeBusy, now) {
  const busy = busyFromFreeBusy(freeBusy);
  if (busy === null) {
    return { statusCode: 200, response: toolError(prepared.toolCallId, 'calendar_unavailable', 'Could not read the calendar.') };
  }
  const { start, end } = slotFromPrepared(prepared);
  const payload = checkAvailability(start, end, busy, prepared.settings, now);
  return { statusCode: 200, response: toolResult(prepared.toolCallId, payload) };
}

// "Confirm slot is still free": re-checks the slot right before creating the event.
function bookingGuard(prepared, freeBusy) {
  const busy = busyFromFreeBusy(freeBusy);
  if (busy === null) {
    return {
      slotFree: false,
      statusCode: 200,
      response: toolError(prepared.toolCallId, 'calendar_unavailable', 'Could not read the calendar. Nothing was booked.'),
    };
  }
  const { start, end } = slotFromPrepared(prepared);
  if (!isSlotFree(start, end, busy)) {
    return {
      slotFree: false,
      statusCode: 200,
      response: toolError(prepared.toolCallId, 'slot_taken', 'The slot is no longer free. Nothing was booked.'),
    };
  }
  return { slotFree: true, event: prepared.event };
}

// "Build booking result": success only when Google Calendar returned the created event.
function bookingResponse(prepared, created) {
  const ok = isObject(created) && typeof created.id === 'string' && created.id !== '' && !created.error;
  if (!ok) {
    return {
      statusCode: 200,
      response: toolError(prepared.toolCallId, 'calendar_error', 'The calendar event could not be created. Nothing was booked.'),
    };
  }
  const { start } = slotFromPrepared(prepared);
  return { statusCode: 200, response: toolResult(prepared.toolCallId, { status: 'ok', ...describeSlot(start, prepared.settings) }) };
}

// Node logic: runs once per request. $now is the current time (Luxon).
return [{ json: prepareToolRequest($input.first().json, $now) }];

// Answers check_availability: the requested slot, or the nearest free alternatives.
// Helper functions first (shared by the Code nodes of this template); the node logic is at the end.

// Helpers shared by the Code nodes of this template.
//
// Each Code node carries its own copy of the helper functions it needs, so
// every node works on its own. `DateTime` is Luxon, which n8n provides in Code nodes.

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

// First non-empty value among `keys`, as a trimmed string ('' if none).
function pickString(source, keys) {
  if (!isObject(source)) return '';
  for (const key of keys) {
    const value = source[key];
    if (typeof value === 'string' && value.trim() !== '') return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
}

// True for empty values and for placeholders that were not replaced, such as "CHANGE_ME".
function isPlaceholder(value) {
  if (typeof value !== 'string') return true;
  const text = value.trim();
  return text === '' || text.includes('{{') || /^change[_ -]?me/i.test(text);
}

// Vapi tool-call parsing and tool-result format.
//
// Vapi posts {"message": {"type": "tool-calls", "toolCallList": [...], ...}}.
// Each call has an `id` and either `function: {name, arguments}` or, in some
// examples of the docs, `name` and `parameters`. `arguments` can arrive as an
// object or as a JSON string. `message.toolWithToolCallList[].toolCall` carries
// the same calls, and the OpenAI-style `message.toolCalls` is accepted too.

function parseArguments(raw) {
  if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      return isObject(parsed) ? parsed : {};
    } catch (error) {
      return {};
    }
  }
  return isObject(raw) ? raw : {};
}

function listToolCalls(message) {
  if (!isObject(message)) return [];
  if (Array.isArray(message.toolCallList) && message.toolCallList.length) return message.toolCallList;
  if (Array.isArray(message.toolCalls) && message.toolCalls.length) return message.toolCalls;
  if (Array.isArray(message.toolWithToolCallList)) {
    return message.toolWithToolCallList
      .filter((entry) => isObject(entry) && isObject(entry.toolCall))
      .map((entry) => ({
        ...entry.toolCall,
        name: entry.toolCall.name || entry.name || (isObject(entry.function) ? entry.function.name : undefined),
      }));
  }
  return [];
}

// Returns {source, toolCallId, name, args}. Picks the call named `expectedName`
// if there is one, otherwise the first call. Without a Vapi envelope it falls
// back to the plain body, e.g. {"date": "2026-10-14", "time": "10:00"}.
function parseToolCall(body, expectedName) {
  const calls = listToolCalls(isObject(body) ? body.message : undefined)
    .filter(isObject)
    .map((call) => {
      const fn = isObject(call.function) ? call.function : {};
      return {
        source: 'vapi',
        toolCallId: typeof call.id === 'string' ? call.id : null,
        name: fn.name || call.name || null,
        args: parseArguments(fn.arguments !== undefined ? fn.arguments : (call.parameters !== undefined ? call.parameters : call.arguments)),
      };
    });

  if (calls.length) {
    return calls.find((call) => expectedName && call.name === expectedName) || calls[0];
  }

  const plain = isObject(body) ? body : {};
  return {
    source: 'plain',
    toolCallId: typeof plain.toolCallId === 'string' ? plain.toolCallId : null,
    name: expectedName || null,
    args: plain,
  };
}

// Vapi expects HTTP 200 with one entry per tool call; `result` and `error` must be flat strings.
function toolResult(toolCallId, payload) {
  return { results: [{ toolCallId, result: JSON.stringify(payload) }] };
}

function toolError(toolCallId, code, message) {
  return { results: [{ toolCallId, error: JSON.stringify({ status: 'error', code, message }) }] };
}

// Slot rules: requested slot, opening hours, busy intervals and alternatives.
// Times are Luxon DateTimes in the configured timezone.

// Reads {date: "YYYY-MM-DD", time: "HH:mm"}. Also accepts one combined
// "YYYY-MM-DD HH:mm" (or ISO "YYYY-MM-DDTHH:mm") value in `datetime`.
function readSlotArgs(args) {
  let date = pickString(args, ['date']);
  let time = pickString(args, ['time']);
  const combined = pickString(args, ['datetime', 'dateTime', 'date_time']);
  if ((!date || !time) && combined) {
    const match = /^(\d{4}-\d{2}-\d{2})[ T](\d{1,2}:\d{2})/.exec(combined);
    if (match) {
      date = date || match[1];
      time = time || match[2];
    }
  }
  return { date, time };
}

// The requested start, in the configured timezone, and its end after the visit duration.
function toSlot(date, time, settings) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date || '')) {
    return { ok: false, code: 'invalid_date', message: 'date must be YYYY-MM-DD' };
  }
  const clock = parseClock(time);
  if (!clock) return { ok: false, code: 'invalid_time', message: 'time must be HH:mm' };
  const start = DateTime.fromISO(date, { zone: settings.timezone }).set({ hour: clock.hour, minute: clock.minute });
  if (!start.isValid) return { ok: false, code: 'invalid_date', message: 'date is not a valid date' };
  return { ok: true, start, end: start.plus({ minutes: settings.slotMinutes }) };
}

function isWithinOpeningHours(start, end, settings) {
  const local = start.setZone(settings.timezone);
  if (!settings.openDays.includes(local.weekday)) return false;
  const open = local.set({ hour: settings.openFrom.hour, minute: settings.openFrom.minute, second: 0, millisecond: 0 });
  const close = local.set({ hour: settings.openTo.hour, minute: settings.openTo.minute, second: 0, millisecond: 0 });
  return start >= open && end <= close;
}

// Why a slot cannot be offered regardless of the calendar, or null.
function slotProblem(start, end, settings, now) {
  if (start < now) return 'in_the_past';
  if (start < now.plus({ minutes: settings.minNoticeMinutes })) return 'too_soon';
  if (!isWithinOpeningHours(start, end, settings)) return 'outside_opening_hours';
  return null;
}

function toIntervals(busy) {
  return (Array.isArray(busy) ? busy : [])
    .filter(isObject)
    .map((entry) => ({ start: DateTime.fromISO(String(entry.start)), end: DateTime.fromISO(String(entry.end)) }))
    .filter((entry) => entry.start.isValid && entry.end.isValid && entry.end > entry.start);
}

