// Days searched for alternatives: `searchDays` around the requested day, never before today.
// The freeBusy query covers the same range, so every alternative was checked against it.
function searchRange(requestedStart, settings, now) {
  const today = now.setZone(settings.timezone).startOf('day');
  const from = DateTime.max(requestedStart.minus({ days: settings.searchDays }).startOf('day'), today);
  const to = DateTime.max(requestedStart, now.setZone(settings.timezone)).plus({ days: settings.searchDays }).endOf('day');
