// if there is one, otherwise the first call. Without a Vapi envelope it falls
// back to the plain body, e.g. {"date": "2026-10-14", "time": "10:00"}.
function parseToolCall(body, expectedName) {
  const calls = listToolCalls(isObject(body) ? body.message : undefined)
    .filter(isObject)
    .map((call) => {
      const fn = isObject(call.function) ? call.function : {};
      return {
        source: 'vapi',
        toolCallId: typeof call.id === 'string' ? call.id : null,
        name: fn.name || call.name || null,
        args: parseArguments(fn.arguments !== undefined ? fn.arguments : (call.parameters !== undefined ? call.parameters : call.arguments)),
      };
    });

  if (calls.length) {
    return calls.find((call) => expectedName && call.name === expectedName) || calls[0];
  }

  const plain = isObject(body) ? body : {};
